# Generated by build.py from recipe.yml for recipe https-serve-http3. Do not edit.
Set-Location $PSScriptRoot
New-Item -ItemType Directory -Force -Path 'site', 'plain' | Out-Null
[IO.File]::WriteAllText((Join-Path $PWD 'site/hello.txt'), "hello from surl`n")
[IO.File]::WriteAllText((Join-Path $PWD 'plain/hello.txt'), "hello from surl`n")
cmd /c 'openssl req -x509 -newkey rsa:2048 -nodes -keyout server.key -out server.pem -days 30 -subj "/CN=127.0.0.1" -addext "subjectAltName=IP:127.0.0.1"'
$server0 = Start-Process surl -ArgumentList '--directory', 'site', '--cert', 'server.pem', '--key', 'server.key', '--http3', 'https://127.0.0.1:8080/' -PassThru -NoNewWindow
Start-Sleep 1
try { curl.exe --http3-only --cacert server.pem -w "HTTP/%{http_version}\n" https://127.0.0.1:8080/hello.txt } finally { Stop-Process $server0 }
